<?php use App\Core\View; ?>
<section class="orientation-page">
 <div class="orientation-head"><span class="dashboard-eyebrow">MIEUX TE CONNAÎTRE</span><h1>Ton test d’orientation</h1><p>Réponds spontanément : il n’y a pas de bonne ou de mauvaise réponse. Tes réponses servent à faire émerger des pistes de réflexion.</p></div>
 <?php if($success): ?><div class="test-alert success" role="status"><?=View::escape($success)?></div><?php endif ?>
 <?php if($errors): ?><div class="test-alert error" role="alert"><?php foreach($errors as $e):?><p><?=View::escape($e)?></p><?php endforeach?></div><?php endif ?>
 <?php if(!$profile||!$profile['bac_series_id']): ?><article class="test-state"><div class="test-state-icon">◎</div><h2>Commence par renseigner ta série du BAC</h2><p>Cette information est nécessaire pour commencer ton parcours d’orientation.</p><a class="test-primary" href="<?=View::escape($basePath)?>/profil">Compléter mon profil <span>↗</span></a></article>
 <?php elseif(!$questions): ?><article class="test-state"><div class="test-state-icon">✳</div><h2>Le questionnaire se prépare</h2><p>Aucune question active n’a encore été publiée. Reviens bientôt pour commencer ton test.</p><a class="test-secondary" href="<?=View::escape($basePath)?>/dashboard">Retour au tableau de bord</a></article>
 <?php else: ?>
 <?php if($completed): ?><section class="test-results"><div class="results-heading"><span class="dashboard-eyebrow">TON DERNIER RÉSULTAT · <?=View::escape((string)$completed['completed_at'])?></span><h2>Les domaines qui te correspondent</h2><p>Ces résultats sont des pistes à explorer, construites à partir de tes réponses. Elles ne remplacent pas les conseils d’un professionnel.</p></div><?php if($results):?><div class="result-list"><?php foreach($results as $x):$pct=(float)$x['percentage'];$affinity=$pct>=70?'Affinité très forte':($pct>=50?'Affinité forte':'Affinité notable');$phrase=$pct>=70?'Ton profil correspond très nettement à ce domaine.':($pct>=50?'Ce domaine ressort clairement de tes réponses.':'Ce domaine est une piste sérieuse à explorer.');?><article class="result-card"><span class="result-rank">#<?= (int)$x['rank_position']?></span><div class="result-info"><h3><?=View::escape($x['name'])?></h3><small class="result-affinity"><?=View::escape($affinity)?> — <?=View::escape($phrase)?></small><?php if($x['description']):?><p><?=View::escape($x['description'])?></p><?php endif?><div class="result-meter"><span style="width:<?=max(0,min(100,$pct))?>%"></span></div></div><strong><?=number_format($pct,2,',',' ')?> %</strong></article><?php endforeach?></div><?php else:?><p class="no-recommendation">Aucun domaine ne dépasse le seuil de 30 %. Consulte les domaines les mieux classés comme pistes d’exploration.</p><?php endif?><a class="test-primary results-detail-link" href="<?=View::escape($basePath)?>/resultats">Voir les formations, établissements et métiers associés <span>↗</span></a></section><?php endif?>
 <div class="test-intro-row"><div><span class="dashboard-eyebrow">QUESTIONNAIRE</span><h2><?= $completed?'Repasser le test':($testId?'Reprendre ton test':'Prêt à commencer ?')?></h2><p><?=count($questions)?> questions au questionnaire</p></div><form action="<?=View::escape($basePath)?>/test-orientation" method="post"><input type="hidden" name="_csrf_token" value="<?=View::escape($csrfToken)?>"><button class="test-primary" type="submit"><?= $testId?'Reprendre le test':($completed?'Commencer un nouveau test':'Commencer le test')?> <span>↗</span></button></form></div>
 <?php if($testId): ?><form class="questionnaire-form" action="<?=View::escape($basePath)?>/test-orientation/reponses" method="post"><input type="hidden" name="_csrf_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="test_id" value="<?= (int)$testId?>"><?php foreach($questions as $i=>$q):?><fieldset class="question-card"><legend><span class="question-number"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><span><?=View::escape($q['text'])?><?= $q['required']?'<b class="required-star">*</b>':''?></span></legend><?php if($q['help']):?><p class="question-help"><?=View::escape($q['help'])?></p><?php endif?><div class="answer-options"><?php foreach($q['options'] as $o):$checked=in_array($o['id'],$answers[$q['id']]??[],true);$type='radio';$name='answers['.$q['id'].']';?><label class="answer-option"><input type="<?=$type?>" name="<?=View::escape($name)?>" value="<?=$o['id']?>" <?=$checked?'checked':''?>><span class="answer-check"></span><span><?=View::escape($o['text'])?></span></label><?php endforeach?></div></fieldset><?php endforeach?><div class="questionnaire-submit"><p><b>*</b> Une réponse obligatoire par question. Tu peux revenir en arrière avant de valider.</p><button class="test-primary" type="submit">Valider le test <span>↗</span></button></div></form><?php endif ?>
 <?php endif ?>
</section>
<?php if($questions && $testId): ?><script>
(() => {
 const form=document.querySelector('.questionnaire-form'); if(!form)return;
 const cards=[...form.querySelectorAll('.question-card')];let index=0;let saving=Promise.resolve();
 const nav=document.createElement('div');nav.className='question-nav';nav.innerHTML='<button type="button" class="test-secondary" data-prev>← Précédent</button><div class="question-progress"><span data-label></span><div class="question-progress-track"><i></i></div><small data-save aria-live="polite">Ta réponse est enregistrée automatiquement</small></div><button type="button" class="test-primary" data-next>Suivant →</button>';
 const validation=document.createElement('div');validation.className='question-validation';validation.setAttribute('role','alert');validation.hidden=true;form.insertBefore(validation,nav);
 const footer=form.querySelector('.questionnaire-submit');form.insertBefore(nav,footer);
 const prev=nav.querySelector('[data-prev]'),next=nav.querySelector('[data-next]'),label=nav.querySelector('[data-label]'),bar=nav.querySelector('i'),save=nav.querySelector('[data-save]');
 function show(i){index=Math.max(0,Math.min(i,cards.length-1));cards.forEach((c,n)=>{c.hidden=n!==index});prev.disabled=index===0;next.textContent=index===cards.length-1?'Vérifier mes réponses':'Suivant →';label.textContent=`Question ${index+1} sur ${cards.length}`;bar.style.width=`${(index+1)*100/cards.length}%`;footer.hidden=index!==cards.length-1;}
 prev.addEventListener('click',()=>show(index-1));next.addEventListener('click',()=>{if(index<cards.length-1){const selected=cards[index].querySelector('input:checked');if(!selected){cards[index].querySelector('input')?.focus();return}show(index+1)}else{form.scrollIntoView({behavior:'smooth',block:'end'})}});
 form.addEventListener('change',e=>{if(!e.target.matches('input[type=radio]'))return;const card=e.target.closest('.question-card');const questionId=card.querySelector('input').name.match(/answers\[(\d+)\]/)?.[1];save.textContent='Enregistrement…';save.classList.remove('save-error');saving=saving.then(()=>fetch('<?=View::escape($basePath)?>/test-orientation/reponse',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({_csrf_token:form.querySelector('[name="_csrf_token"]').value,test_id:form.querySelector('[name="test_id"]').value,question_id:questionId,option_id:e.target.value})})).then(async r=>{const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'La réponse n’a pas pu être enregistrée.');save.textContent='Réponse enregistrée ✓';}).catch(error=>{save.textContent=error.message;save.classList.add('save-error');});});
 let resubmitting=false;form.addEventListener('submit',async e=>{if(resubmitting)return;e.preventDefault();validation.hidden=true;await saving;if(save.classList.contains('save-error')){validation.textContent='Une réponse n’a pas été enregistrée. Vérifie ta connexion puis sélectionne-la à nouveau.';validation.hidden=false;return;}const unanswered=cards.find(c=>!c.querySelector('input:checked'));if(unanswered){show(cards.indexOf(unanswered));validation.textContent=`Il manque une réponse à la question ${cards.indexOf(unanswered)+1}. Choisis une proposition avant de valider le test.`;validation.hidden=false;unanswered.scrollIntoView({behavior:'smooth',block:'center'});unanswered.querySelector('input')?.focus();return;}resubmitting=true;form.requestSubmit(e.submitter);});
 const firstUnanswered=cards.findIndex(card=>!card.querySelector("input:checked"));show(firstUnanswered<0?0:firstUnanswered);
})();
</script><?php endif ?>





